### `middleware/rawBody.js`

> **Critical:** Signature verification requires the **raw, unmodified request body** as bytes. If you parse JSON first, the signature will never match.

```javascript
import express from 'express';

/**
 * Attach the raw body buffer to the request object BEFORE
 * any JSON parsing occurs. Register this before express.json().
 */
export function rawBodyMiddleware(req, res, next) {
  let data = [];

  req.on('data', (chunk) => {
    data.push(chunk);
  });

  req.on('end', () => {
    req.rawBody = Buffer.concat(data);
    // Now let express parse the JSON from the string version
    req.body = JSON.parse(req.rawBody.toString('utf8'));
    next();
  });

  req.on('error', (err) => {
    console.error('[rawBody] Stream error:', err.message);
    res.status(400).json({ error: 'Failed to read request body' });
  });
}
```

