### **3.4. Step 3: Submit Signed Hash to Blockchain**
The agent submits the **signed hash + CID** to the smart contract.

#### **Smart Contract Interaction (Solidity)**
```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract TreasuryAudit {
    bytes32[] public transactionHashes;
    mapping(bytes32 => string) public cidToMetadata;

    function storeTransactionHash(
        bytes32 _hash,
        string memory _cid,
        bytes memory _signature,
        uint8 _recovery
    ) external {
        require(verifySignature(_hash, _signature, _recovery), "Invalid signature");
        transactionHashes.push(_hash);
        cidToMetadata[_hash] = _cid;
    }

    function verifySignature(
        bytes32 _hash,
        bytes memory _signature,
        uint8 _recovery
    ) internal view returns (bool) {
        // Implement ECDSA verification (e.g., using OpenZeppelin)
        return ecrecover(_hash, _signature, _recovery) != address(0);
    }
}
```

