### **Step 1: Create a Validation Hook**
```javascript
// hooks/useTaxIDValidation.js
import { useState } from 'react';

export const useTaxIDValidation = () => {
  const [isValid, setIsValid] = useState(false);
  const [error, setError] = useState('');

  const validateTaxID = (taxID) => {
    if (!taxID) {
      setError('Tax ID is required.');
      setIsValid(false);
      return false;
    }

    if (!/^TID-\d{4}-\d{4}-\d{4}-\d{4}$/.test(taxID)) {
      setError('Invalid format. Use TID-XXXX-XXXX-XXXX.');
      setIsValid(false);
      return false;
    }

    const digits = taxID.replace(/[^0-9]/g, '').split('').map(Number);
    const sum = digits.slice(0, -1).reduce((acc, val) => acc + val, 0);
    const expectedLastDigit = sum % 10;
    const actualLastDigit = digits[digits.length - 1];

    if (expectedLastDigit !== actualLastDigit) {
      setError('Invalid checksum. Tax ID is incorrect.');
      setIsValid(false);
      return false;
    }

    setError('');
    setIsValid(true);
    return true;
  };

  return { validateTaxID, isValid, error };
};
```

